"""RoboPaint session record. Motions use only documented robot API and camera observations."""
import sys,json,time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); r=Robot()
Q=np.array([-3.987430829965888e-7,1.,-3.555323928594589e-7,-2.8657268558163196e-8])
Z=.02020

def current(): return np.array(r.get_obs(cameras=[],video='none').meta['proprio']['now'][7:14])

def send(rows,note='motion',cams=('practice_cam',)):
 rows=np.asarray(rows)
 for i in range(0,len(rows),180):
  chunk=rows[i:i+180]
  idx=len(list(OUT.glob('call_*.npz')))
  np.savez(OUT/f'call_{idx:04}.npz',actions=chunk,dt=.05,note=note)
  before=r.status()
  try:res=r.submit('ee_pose',chunk,dt=.05,cameras=list(cams),video='none',video_fps=20,note=note)
  except Exception:
   r.wait_ready(); print('RECOVERY',before,r.status(),flush=True);raise
  (OUT/f'call_{idx:04}.json').write_text(json.dumps(res.meta,indent=1))
  if res.proprio is not None:np.save(OUT/f'proprio_{idx:04}.npy',res.proprio)
  for c,im in res.last.items():Image.fromarray(im).save(OUT/f'latest_{c}.png')
  print(idx,note,'steps',res.meta.get('control_steps_chunk'),'tip',res.meta['proprio']['now'][7:10],'plan',res.meta.get('plan'),flush=True)
  if res.stopped:raise RuntimeError('partial call')
 return res

def line(a,b,speed=.03):
 n=max(1,int(np.ceil(np.linalg.norm(np.array(b)-a)/(speed*.05))))
 return np.c_[np.linspace(a,b,n+1)[1:],np.tile(Q,(n,1))]

def move(p,speed=.04,hold=.3,note='travel'):
 a=current()[:3]; rows=line(a,p,speed)
 if hold:rows=np.r_[rows,np.tile(np.r_[p,Q],(int(hold/.05),1))]
 return send(rows,note)

def dip():
 a=current()[:3];move([a[0],a[1],.075]);move([-.100,.151,.075]);move([-.100,.151,.025],.025,.5,'dip ink');move([-.100,.151,.075])

def park():
 a=current()[:3];move([a[0],a[1],.075]);move([-.1,.15,.075]);
 o=r.get_obs(cameras=['practice_cam','canvas_cam','scene_cam'],depth=True)
 for c,im in o.last.items():Image.fromarray(im).save(OUT/f'latest_{c}.png')
 o.save(str(OUT/'last_observation'))

if __name__=='__main__':
 if sys.argv[1]=='calibrate':
  dip()
  for j,dep in enumerate([.001,.003,.005,.008,.012,.016]):
   x=-.025-j*.029
   move([x,-.153,.055]);move([x,-.153,Z-dep],.015,.4,'press '+str(dep))
   send(line([x,-.153,Z-dep],[x,-.218,Z-dep],.012),'width test '+str(dep))
   move([x,-.218,.055],.02,.2,'lift')
  park()
PY
